    """Minimal float64 .npy reader (no numpy needed)."""
    data = Path(path).read_bytes()
    assert data[:6] == b"\x93NUMPY"
    major = data[6]
    if major == 1:
        hl = int.from_bytes(data[8:10], "little")
        off = 10 + hl
    else:
        hl = int.from_bytes(data[8:12], "little")
        off = 12 + hl
    rest = data[off:]
